#!/usr/bin/env python3
import os, json, math, numpy as np

# ---------------------------------------------------------------------
# Physical constants (SI) – required by the spec, even if not used later
# ---------------------------------------------------------------------
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8        # m·s⁻¹
hbar = 1.054571817e-34  # J·s
k_B = 1.380649e-23      # J·K⁻¹
M_sun = 1.98847e30      # kg

def load_gwtc_catalog():
    """Load the GWTC catalog JSON and return the list of events.
    The environment variable GWTC_CATALOG_PATH must point to a JSON file with the
    structure {"events": [{"event_id": ..., "mass_1_source": ..., "mass_2_source": ..., ...}, ...]}
    """
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        raise RuntimeError('Environment variable GWTC_CATALOG_PATH not set')
    with open(path, 'r') as f:
        data = json.load(f)
    return data.get('events', [])

def total_mass(event):
    m1 = event.get('mass_1_source')
    m2 = event.get('mass_2_source')
    if None in (m1, m2):
        return None
    return float(m1) + float(m2)

def main():
    events = load_gwtc_catalog()
    results = []
    for ev in events:
        M_tot = total_mass(ev)
        if M_tot is None:
            continue
        results.append(M_tot)
    if not results:
        print('No valid events found')
        return
    # Simple sanity check: non‑negative mass
    for M in results:
        assert M > 0, f'Unexpected non‑positive total mass: {M}'
    print(f"Analyzed {len(results)} events with valid total mass.")

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import numpy as np, json, os, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius_schwarzschild(M):
    return 6 * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * np.pi * G * M * k_B)

def planck_length():
    return np.sqrt(hbar * G / c**3)

def bh_entropy(M):
    r_s = schwarzschild_radius(M)
    r_isco = isco_radius_schwarzschild(M)
    area = 4 * np.pi * r_isco**2
    l_p2 = planck_length()**2
    return area / (4 * l_p2)

def main():
    # Example masses (10 solar masses, 30 solar masses, 1e6 solar masses)
    masses = [10 * M_sun, 30 * M_sun, 1e6 * M_sun]
    results = []
    for M in masses:
        r_s = schwarzschild_radius(M)
        r_isco = isco_radius_schwarzschild(M)
        T = hawking_temperature(M)
        l_p = planck_length()
        S = bh_entropy(M)
        results.append({
            "mass_kg": M,
            "schwarzschild_radius_m": r_s,
            "isco_radius_m": r_isco,
            "hawking_temperature_K": T,
            "planck_length_m": l_p,
            "bh_entropy_bits": S / (np.log(2) * k_B)  # convert natural log to bits
        })
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

